//! Golden-fixture agreement with the independent SciPy reference.
//!
//! Reads the committed fixture ELTs and golden outputs under `fixtures/`
//! (regenerated by `uv run python fixtures/generate_fixtures.py`) and checks
//! the Rust implementation against them.

use std::path::PathBuf;

use eltq_core::{Category, Config, EltInput, quantize};

fn fixtures_dir() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../../fixtures")
}

struct Columns {
    rate: Vec<f64>,
    max_loss: Vec<f64>,
    mean_loss: Vec<f64>,
    sd_indep: Vec<f64>,
    sd_corr: Vec<f64>,
}

fn read_elt(name: &str) -> Columns {
    let text = std::fs::read_to_string(fixtures_dir().join(format!("{name}_elt.csv"))).unwrap();
    let mut lines = text.lines();
    assert_eq!(
        lines.next().unwrap().trim(),
        "event_id,rate,max_loss,mean_loss,sd_indep,sd_corr"
    );
    let mut cols = Columns {
        rate: Vec::new(),
        max_loss: Vec::new(),
        mean_loss: Vec::new(),
        sd_indep: Vec::new(),
        sd_corr: Vec::new(),
    };
    for line in lines.filter(|l| !l.trim().is_empty()) {
        let fields: Vec<&str> = line.split(',').collect();
        assert_eq!(fields.len(), 6, "bad fixture line: {line}");
        cols.rate.push(fields[1].parse().unwrap());
        cols.max_loss.push(fields[2].parse().unwrap());
        cols.mean_loss.push(fields[3].parse().unwrap());
        cols.sd_indep.push(fields[4].parse().unwrap());
        cols.sd_corr.push(fields[5].parse().unwrap());
    }
    cols
}

fn read_golden_arrays(name: &str) -> (Vec<f64>, Vec<f64>) {
    let path = fixtures_dir().join(format!("golden/{name}.arrays.csv"));
    let text = std::fs::read_to_string(path).unwrap();
    let mut lines = text.lines();
    assert_eq!(lines.next().unwrap().trim(), "raw,secondary");
    let mut raw = Vec::new();
    let mut secondary = Vec::new();
    for line in lines.filter(|l| !l.trim().is_empty()) {
        let (a, b) = line.split_once(',').unwrap();
        raw.push(a.trim().parse().unwrap());
        secondary.push(b.trim().parse().unwrap());
    }
    (raw, secondary)
}

fn assert_arrays_close(label: &str, got: &[f64], want: &[f64], rtol: f64, atol: f64) {
    assert_eq!(got.len(), want.len(), "{label}: length mismatch");
    for (i, (&g, &w)) in got.iter().zip(want).enumerate() {
        let tolerance = atol + rtol * w.abs();
        assert!(
            (g - w).abs() <= tolerance,
            "{label}[{i}]: got {g}, want {w} (diff {})",
            (g - w).abs()
        );
    }
}

fn check_golden(name: &str) {
    let cols = read_elt(name);
    let (golden_raw, golden_secondary) = read_golden_arrays(name);
    let meta_json: serde_json::Value = serde_json::from_str(
        &std::fs::read_to_string(fixtures_dir().join(format!("golden/{name}.meta.json"))).unwrap(),
    )
    .unwrap();

    let mut config = Config::new(meta_json["params"]["bucket_size"].as_f64().unwrap());
    config.quadrature_points = meta_json["params"]["quadrature_points"].as_u64().unwrap() as usize;
    let input = EltInput {
        rate: &cols.rate,
        max_loss: &cols.max_loss,
        mean_loss: &cols.mean_loss,
        sd_indep: &cols.sd_indep,
        sd_corr: &cols.sd_corr,
    };
    let result = quantize(&input, &config).unwrap();
    let meta = &result.meta;

    assert_eq!(meta.grid_length, meta_json["grid_length"].as_u64().unwrap() as usize);
    assert_eq!(meta.valid_rows, meta_json["valid_rows"].as_u64().unwrap() as usize);

    let total_rate = meta_json["total_rate"].as_f64().unwrap();
    let atol = 1e-13 * total_rate;
    assert_arrays_close("raw", &result.raw, &golden_raw, 1e-9, atol);
    assert_arrays_close("secondary", &result.secondary, &golden_secondary, 1e-9, atol);

    let rel = |got: f64, want: f64| (got - want).abs() / want.abs().max(f64::MIN_POSITIVE);
    assert!(rel(meta.total_rate, total_rate) < 1e-12);
    assert!(rel(meta.analytic_aal, meta_json["analytic_aal"].as_f64().unwrap()) < 1e-12);
    assert!(
        rel(
            meta.quadrature_secondary_mean,
            meta_json["quadrature_secondary_mean"].as_f64().unwrap()
        ) < 1e-9
    );

    // Diagnostics: identical per-category counts (and no unexpected ones).
    let golden_diag = meta_json["diagnostics"].as_object().unwrap();
    for category in Category::ALL {
        let want = golden_diag
            .get(category.as_str())
            .map(|v| v["count"].as_u64().unwrap())
            .unwrap_or(0);
        assert_eq!(
            meta.diagnostics.get(category).count,
            want,
            "category {}",
            category.as_str()
        );
    }
}

#[test]
fn small_golden() {
    check_golden("small");
}

#[test]
fn medium_golden() {
    check_golden("medium");
}
